#!/usr/bin/env python3
"""Reproduce checked-in runtime engine from preserved legacy A/B prefixes."""
import argparse
import pathlib
import sys
ROOT = pathlib.Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / 'experiments/vm-threaded-dispatch'))
from generate import generate, NAMES

def artifacts():
    core = ROOT / 'RiskDetectorApp/Sources/CRiskCore'
    source = (core / 'cprisk_vm_interpreter.c').read_text()
    body = generate(source).replace('Generated validation-only engine; include after interpreter source.',
                                    'Generated by experiments/vm-cpsv-v2/generate_runtime.py; do not edit.')
    body = body.replace('typedef struct {\n    cprisk_vm_interp_frame_t *fr;',
                        'typedef struct cprisk_thread_context_i {\n    cprisk_vm_interp_frame_t *fr;')
    body = body.replace('static void cprisk_thread_run_', 'static __attribute__((noinline, used)) void cprisk_thread_run_')
    names = ['cprisk_vm_execute', 'cprisk_vm_interp_loop_a', 'cprisk_vm_dispatch_lookup',
             'cprisk_vm_oph_post_handler_i', 'cprisk_thread_run_a_i', 'cprisk_thread_run_b_i']
    names += [f'cprisk_thread_{l}_{n}_i' for l in 'ab' for n in NAMES]
    roster = '/* Generated independent compiled identities, in wire kind order. */\n'
    roster += ''.join(f'CPRISK_CPSV2_IDENTITY({n})\n' for n in names)
    return {core/'cprisk_vm_threaded.inc': body, core/'cprisk_vm_cpsv2_roster.inc': roster}

if __name__ == '__main__':
    p = argparse.ArgumentParser(); p.add_argument('--check', action='store_true'); a=p.parse_args()
    for path, body in artifacts().items():
        if a.check:
            assert path.read_text() == body, f'Generated file drift: {path}'
        else: path.write_text(body)
